  2	import {
  3	  LeaveRequest,
  4	  CreateLeaveRequestDto,
  5	  UpdateLeaveRequestDto,
  6	  LeaveRequestQueryParams,
  7	} from './leave-request.model';
  8	import { ILeaveRequestRepository } from './leave-request.repository';
  9	import { IEmployeeService } from 'modules/employee';
 10	import { ILeavePolicyService } from 'modules/leave-policy';
 11	import { ILeaveBalanceService } from 'modules/balance';
 12	import { LeaveStatus, LeaveType } from 'shared/types';
 13	import { NotFoundError, ValidationError, ConflictError } from 'shared/error-types';
 14	
 15	export interface ILeaveRequestService {
 16	  create(dto: CreateLeaveRequestDto): Promise<LeaveRequest>;
 17	  submit(id: string): Promise<LeaveRequest>;
 18	  approve(id: string, approverId: string): Promise<LeaveRequest>;
 19	  reject(id: string, approverId: string): Promise<LeaveRequest>;
 20	  cancel(id: string, cancelledBy: string): Promise<LeaveRequest>;
 21	  update(id: string, dto: UpdateLeaveRequestDto): Promise<LeaveRequest>;
 22	  getById(id: string): Promise<LeaveRequest>;
 23	  query(params: LeaveRequestQueryParams): Promise<LeaveRequest[]>;
 24	  getEmployeeRequests(employeeId: string): Promise<LeaveRequest[]>;
 25	}
 26	
 27	export class LeaveRequestService implements ILeaveRequestService {
 28	  constructor(
 29	    private readonly leaveRequestRepository: ILeaveRequestRepository,
 30	    private readonly employeeService: IEmployeeService,
 31	    private readonly leavePolicyService: ILeavePolicyService,
 32	    private readonly leaveBalanceService: ILeaveBalanceService,
 33	  ) {}
 34	
 35	  async create(dto: CreateLeaveRequestDto): Promise<LeaveRequest> {
 36	    if (dto.endDate < dto.startDate) {
 37	      throw new ValidationError('endDate must be on or after startDate');
 38	    }
 39	
 40	    const employee = await this.employeeService.getById(dto.employeeId);
 41	    if (employee.employmentStatus !== 'ACTIVE') {
 42	      throw new ValidationError('Employee is not active');
 43	    }
 44	
 45	    const policy = await this.leavePolicyService.getById(dto.leavePolicyId);
 46	    if (!policy.isActive) {
 47	      throw new ValidationError('Leave policy is not active');
 48	    }
 49	
 50	    const leaveRequest = await this.leaveRequestRepository.create({
 51	      employeeId: dto.employeeId,
 52	      leavePolicyId: dto.leavePolicyId,
 53	      startDate: dto.startDate,
 54	      endDate: dto.endDate,
 55	      reason: dto.reason,
 56	      status: LeaveStatus.DRAFT,
 57	      approvedBy: null,
 58	      approvedAt: null,
 59	      cancelledBy: null,
 60	      cancelledAt: null,
 61	      createdAt: new Date(),
 62	      updatedAt: new Date(),
 63	    });
 64	
 65	    return leaveRequest;
 66	  }
 67	
 68	  async submit(id: string): Promise<LeaveRequest> {
 69	    const leaveRequest = await this.leaveRequestRepository.findById(id);
 70	    if (!leaveRequest) {
 71	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
 72	    }
 73	
 74	    if (leaveRequest.status !== LeaveStatus.DRAFT) {
 75	      throw new ValidationError(
 76	        `Cannot submit leave request with status ${leaveRequest.status}`,
 77	      );
 78	    }
 79	
 80	    const employee = await this.employeeService.getById(leaveRequest.employeeId);
 81	    if (employee.employmentStatus !== 'ACTIVE') {
 82	      throw new ValidationError('Employee is not active');
 83	    }
 84	
 85	    const policy = await this.leavePolicyService.getById(leaveRequest.leavePolicyId);
 86	    if (!policy.isActive) {
 87	      throw new ValidationError('Leave policy is not active');
 88	    }
 89	
 90	    const isEmergency = policy.leaveType === LeaveType.EMERGENCY;
 91	
 92	    if (!isEmergency && policy.minimumNoticeDays !== null && policy.minimumNoticeDays !== undefined) {
 93	      const now = new Date();
 94	      const noticeMs = leaveRequest.startDate.getTime() - now.getTime();
 95	      const noticeDays = Math.floor(noticeMs / (1000 * 60 * 60 * 24));
 96	      if (noticeDays < policy.minimumNoticeDays) {
 97	        throw new ValidationError(
 98	          `Leave request requires ${policy.minimumNoticeDays} days notice, but only ${noticeDays} days provided`,
 99	        );
100	      }
101	    }
102	
103	    const overlapping = await this.leaveRequestRepository.findOverlapping(
104	      leaveRequest.employeeId,
105	      leaveRequest.startDate,
106	      leaveRequest.endDate,
107	      leaveRequest.id,
108	    );
109	
110	    if (overlapping.length > 0) {
111	      throw new ConflictError('Employee has overlapping leave requests');
112	    }
113	
114	    const daysRequested = this.computeDays(leaveRequest.startDate, leaveRequest.endDate);
115	    const fiscalYear = leaveRequest.startDate.getFullYear();
116	
117	    const remainingDays = await this.leaveBalanceService.getRemainingDays(
118	      leaveRequest.employeeId,
119	      leaveRequest.leavePolicyId,
120	      fiscalYear,
121	    );
122	
123	    if (remainingDays < daysRequested) {
124	      throw new ValidationError(
125	        `Insufficient leave balance: requested ${daysRequested} days but only ${remainingDays} remaining`,
126	      );
127	    }
128	
129	    const updated = await this.leaveRequestRepository.update(id, {
130	      status: LeaveStatus.SUBMITTED,
131	      updatedAt: new Date(),
132	    });
133	
134	    if (!updated) {
135	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
136	    }
137	
138	    return updated;
139	  }
140	
141	  async approve(id: string, approverId: string): Promise<LeaveRequest> {
142	    const leaveRequest = await this.leaveRequestRepository.findById(id);
143	    if (!leaveRequest) {
144	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
145	    }
146	
147	    if (leaveRequest.status !== LeaveStatus.SUBMITTED) {
148	      throw new ValidationError(
149	        `Cannot approve leave request with status ${leaveRequest.status}`,
150	      );
151	    }
152	
153	    const fiscalYear = leaveRequest.startDate.getFullYear();
154	
155	    await this.leaveBalanceService.deductDays(
156	      leaveRequest.employeeId,
157	      leaveRequest.leavePolicyId,
158	      fiscalYear,
159	      leaveRequest.startDate,
160	      leaveRequest.endDate,
161	    );
162	
163	    const updated = await this.leaveRequestRepository.update(id, {
164	      status: LeaveStatus.APPROVED,
165	      approvedBy: approverId,
166	      approvedAt: new Date(),
167	      updatedAt: new Date(),
168	    });
169	
170	    if (!updated) {
171	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
172	    }
173	
174	    return updated;
175	  }
176	
177	  async reject(id: string, approverId: string): Promise<LeaveRequest> {
178	    const leaveRequest = await this.leaveRequestRepository.findById(id);
179	    if (!leaveRequest) {
180	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
181	    }
182	
183	    if (leaveRequest.status !== LeaveStatus.SUBMITTED) {
184	      throw new ValidationError(
185	        `Cannot reject leave request with status ${leaveRequest.status}`,
186	      );
187	    }
188	
189	    const updated = await this.leaveRequestRepository.update(id, {
190	      status: LeaveStatus.REJECTED,
191	      approvedBy: approverId,
192	      approvedAt: new Date(),
193	      updatedAt: new Date(),
194	    });
195	
196	    if (!updated) {
197	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
198	    }
199	
200	    return updated;
201	  }
202	
203	  async cancel(id: string, cancelledBy: string): Promise<LeaveRequest> {
204	    const leaveRequest = await this.leaveRequestRepository.findById(id);
205	    if (!leaveRequest) {
206	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
207	    }
208	
209	    if (
210	      leaveRequest.status !== LeaveStatus.APPROVED &&
211	      leaveRequest.status !== LeaveStatus.SUBMITTED
212	    ) {
213	      throw new ValidationError(
214	        `Cannot cancel leave request with status ${leaveRequest.status}`,
215	      );
216	    }
217	
218	    if (leaveRequest.status === LeaveStatus.APPROVED) {
219	      const daysRequested = this.computeDays(leaveRequest.startDate, leaveRequest.endDate);
220	      const fiscalYear = leaveRequest.startDate.getFullYear();
221	
222	      await this.leaveBalanceService.restoreDays(
223	        leaveRequest.employeeId,
224	        leaveRequest.leavePolicyId,
225	        fiscalYear,
226	        daysRequested,
227	      );
228	    }
229	
230	    const updated = await this.leaveRequestRepository.update(id, {
231	      status: LeaveStatus.CANCELLED,
232	      cancelledBy: cancelledBy,
233	      cancelledAt: new Date(),
234	      updatedAt: new Date(),
235	    });
236	
237	    if (!updated) {
238	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
239	    }
240	
241	    return updated;
242	  }
243	
244	  async update(id: string, dto: UpdateLeaveRequestDto): Promise<LeaveRequest> {
245	    const leaveRequest = await this.leaveRequestRepository.findById(id);
246	    if (!leaveRequest) {
247	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
248	    }
249	
250	    if (leaveRequest.status !== LeaveStatus.DRAFT) {
251	      throw new ValidationError(
252	        `Cannot update leave request with status ${leaveRequest.status}`,
253	      );
254	    }
255	
256	    if (dto.startDate && dto.endDate && dto.endDate < dto.startDate) {
257	      throw new ValidationError('endDate must be on or after startDate');
258	    }
259	
260	    const updateData: Partial<LeaveRequest> = {
261	      ...dto,
262	      updatedAt: new Date(),
263	    };
264	
265	    const updated = await this.leaveRequestRepository.update(id, updateData);
266	
267	    if (!updated) {
268	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
269	    }
270	
271	    return updated;
272	  }
273	
274	  async getById(id: string): Promise<LeaveRequest> {
275	    const leaveRequest = await this.leaveRequestRepository.findById(id);
276	    if (!leaveRequest) {
277	      throw new NotFoundError(`LeaveRequest with id ${id} not found`);
278	    }
279	    return leaveRequest;
280	  }
281	
282	  async query(params: LeaveRequestQueryParams): Promise<LeaveRequest[]> {
283	    if (params.employeeId) {
284	      return this.leaveRequestRepository.findByEmployeeId(params.employeeId);
285	    }
286	
287	    if (params.status) {
288	      return this.leaveRequestRepository.findByStatus(params.status);
289	    }
290	
291	    if (params.startDate && params.endDate) {
292	      return this.leaveRequestRepository.findByDateRange(params.startDate, params.endDate);
293	    }
294	
295	    return this.leaveRequestRepository.findAll();
296	  }
297	
298	  async getEmployeeRequests(employeeId: string): Promise<LeaveRequest[]> {
299	    return this.leaveRequestRepository.findByEmployeeId(employeeId);
300	  }
301	
302	  private computeDays(startDate: Date, endDate: Date): number {
303	    const startMs = startDate.getTime();
304	    const endMs = endDate.getTime();
305	    const diffMs = endMs - startMs;
306	    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
307	    return diffDays + 1;
308	  }
309	}
